-- =====================================================================
-- Consultas de control: cada una debe devolver 0 filas
-- =====================================================================

-- 1. Stock reservado distinto de la suma de ítems en pedidos aceptados o en camino
SELECT pr.id, pr.nombre, pr.stock_reservado,
       COALESCE(SUM(CASE WHEN p.id IS NOT NULL THEN pi.cantidad END), 0) AS reservado_esperado
FROM producto pr
LEFT JOIN pedido_item pi ON pi.producto_id = pr.id
LEFT JOIN pedido p ON p.id = pi.pedido_id AND p.estado IN ('aceptado', 'en_camino')
GROUP BY pr.id
HAVING pr.stock_reservado <> COALESCE(SUM(CASE WHEN p.id IS NOT NULL THEN pi.cantidad END), 0);

-- 2. Productos sin precio base (tramo de cantidad mínima 1)
SELECT pr.id, pr.nombre FROM producto pr
WHERE NOT EXISTS (SELECT 1 FROM precio_volumen pv WHERE pv.producto_id = pr.id AND pv.cantidad_minima = 1);

-- 3. Ítems cuyo tramo no es el que corresponde a su cantidad, o con precio congelado distinto
SELECT pi.id, pi.cantidad, pv.cantidad_minima FROM pedido_item pi
JOIN precio_volumen pv ON pv.id = pi.precio_volumen_id
WHERE pv.producto_id <> pi.producto_id
   OR pv.precio_venta <> pi.precio_venta_congelado
   OR pv.cantidad_minima <> (SELECT MAX(x.cantidad_minima) FROM precio_volumen x
                             WHERE x.producto_id = pi.producto_id AND x.cantidad_minima <= pi.cantidad);

-- 4. Pedidos con ítems de otra distribuidora
SELECT p.id FROM pedido p
JOIN pedido_item pi ON pi.pedido_id = p.id
JOIN producto pr ON pr.id = pi.producto_id
WHERE pr.distribuidor_id <> p.distribuidor_id;

-- 5. Stock disponible negativo
SELECT id, nombre FROM producto WHERE stock_total - stock_reservado < 0;

-- 6. Fechas en el futuro
SELECT 'pedido' AS tabla, id FROM pedido WHERE fecha_creacion > NOW() OR fecha_entregado > NOW()
UNION ALL SELECT 'notificacion', id FROM notificacion WHERE fecha_creacion > NOW()
UNION ALL SELECT 'plan_reparto', id FROM plan_reparto WHERE fecha_creacion > NOW();
